const fs = require("fs")
const path = require("path")

function read(file) {
  return fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n")
}
function ensureParent(file) {
  fs.mkdirSync(path.dirname(file), { recursive: true })
}
function decode(value) {
  return Buffer.from(value, "base64").toString("utf8")
}
function countOf(content, needle) {
  return content.split(needle).length - 1
}
function replaceExact(content, oldText, newText, label) {
  const count = countOf(content, oldText)
  if (count !== 1) {
    throw new Error(`${label}: esperado 1 trecho, encontrado(s) ${count}. Nenhum arquivo existente foi alterado.`)
  }
  return content.replace(oldText, newText)
}

const marketingPanel = path.join("components", "admin", "marketing-panel.tsx")
if (!fs.existsSync(marketingPanel)) {
  throw new Error(`Arquivo obrigatorio nao encontrado: ${marketingPanel}`)
}
if (!fs.existsSync("lib/postgres.ts") || !fs.existsSync("lib/tenant-access.ts")) {
  throw new Error("A base atual do SaborFlow nao foi encontrada. Execute este instalador na raiz do projeto.")
}

let marketing = read(marketingPanel)
if (marketing.includes("MarketingPublicationsPanel")) {
  throw new Error("A Etapa 12 parece ja estar aplicada em components/admin/marketing-panel.tsx.")
}

const generated = {"database/migrations/20261003_etapa12_marketing_publications.sql": "", "lib/marketing-publications-db.ts": "", "app/api/marketing-publications/route.ts": "", "app/api/marketing-publications/[id]/route.ts": "", "app/api/marketing-publications/assets/route.ts": "", "app/api/marketing-publications/assets/[name]/route.ts": "", "components/admin/marketing-publications-panel.tsx": ""}
const backupDir = path.join("_backups", `etapa12-${new Date().toISOString().replace(/[:.]/g, "-")}`)
fs.mkdirSync(backupDir, { recursive: true })
fs.copyFileSync(marketingPanel, path.join(backupDir, "marketing-panel.tsx"))

const importAnchor = '} from "@/lib/types"\n'
marketing = replaceExact(
  marketing,
  importAnchor,
  `${importAnchor}import { MarketingPublicationsPanel } from "@/components/admin/marketing-publications-panel"\n`,
  "Import do painel de publicacoes",
)

const renderAnchor = '  return (\n    <div className="space-y-5">\n'
marketing = replaceExact(
  marketing,
  renderAnchor,
  `${renderAnchor}      <MarketingPublicationsPanel settings={settings} />\n`,
  "Render do painel de publicacoes",
)

for (const [file, content] of Object.entries(generated)) {
  ensureParent(file)
  fs.writeFileSync(file, decode(content), "utf8")
}
fs.writeFileSync(marketingPanel, marketing, "utf8")

console.log("")
console.log("ETAPA 12 aplicada aos arquivos do projeto.")
